import { Component, Input } from '@angular/core';

@Component({
    selector: 'app-datepicker',
    templateUrl: './datepicker.component.html',
    styleUrls: ['./datepicker.component.css']
})
export class DatepickerComponent {
    @Input() dateValue: Date = new Date();
	@Input() timeValueString: string = '00:00';

    dateValueString: string = this.formatDateToDDMMYYYY(this.dateValue);

    @Input() isReadOnly: boolean = false;
    @Input() labelString: string | undefined;
    @Input() showLabel: boolean = true;
    @Input() showOuterDiv: boolean = false;
	@Input() showTimePicker: boolean = false;

	monthsNames: string[] = [
		'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August',
		'September', 'October', 'November', 'December'
	];

	weekDaysNames: string[] = [
		'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'
	];

	calendar: number[][] = [];

	ngOnInit() {
		if(this.labelString === undefined)
		{
			this.labelString = 'Date' + (this.showTimePicker ? ' and Time' : '');
		}
		this.initCalendar();
	}

	initCalendar() {
		const firstDayOfMonth = this.getFirstDayOfMonth(this.dateValue);
		const daysInMonth = new Date(this.dateValue.getFullYear(), this.dateValue.getMonth() + 1, 0).getDate();
		const daysInPrevMonth = new Date(this.dateValue.getFullYear(), this.dateValue.getMonth(), 0).getDate();
		const daysInNextMonth = new Date(this.dateValue.getFullYear(), this.dateValue.getMonth() + 2, 0).getDate();


		let day = 1;
		for (let i = 0; i < 5; i++) {
			this.calendar[i] = [];
			for (let j = 0; j < 7; j++) {
				if (i === 0 && j < firstDayOfMonth) {
					this.calendar[i][j] = daysInPrevMonth - firstDayOfMonth + j + 1;
				} else if (day > daysInMonth) {
					this.calendar[i][j] = day++ - daysInMonth;
				} else {
					this.calendar[i][j] = day++;
				}
			}
		}

		console.log(this.calendar);
	}

	showDatePicker: boolean = false;

    openDatePicker() {
		this.showDatePicker = !this.showDatePicker;
    }

    formatDateToDDMMYYYY(date: Date) {
        // Get day, month, and year components
        const day = date.getDate();
        const month = date.getMonth() + 1; // Months are zero-based, so add 1
        const year = date.getFullYear();

        // Ensure two-digit format for day and month
        const formattedDay = day < 10 ? '0' + day : day;
        const formattedMonth = month < 10 ? '0' + month : month;

        // Combine components in "dd/mm/yyyy" format
        const formattedDate = `${formattedDay}/${formattedMonth}/${year}`;

        return formattedDate;
    }

	getFirstDayOfMonth(date: Date) {
		return new Date(date.getFullYear(), date.getMonth(), 1).getDay()-1;
	}



}
<div
    ngClass="{{ showOuterDiv ? 'default-input' : '' }}"
    class="d-flex flex-wrap"
>
    <label *ngIf="showLabel" for="date" class="default-label">{{
        labelString
    }}</label>

    <div class="datepicker-wrapper">
        <input
            type="text"
            [value]="
                dateValueString + (showTimePicker ? ' ' + timeValueString : '')
            "
            readonly
            (click)="openDatePicker()"
            class="no-style-input inner-input composed-input primary d-flex"
            placeholder="Select Date"
        />

        <div
            class="datepicker-container"
            ngClass="{{ showDatePicker ? 'active' : 'off' }}"
        >
            <div class="datepicker-navbar">
                <span class="datapicker-arrows"> < </span>
                <span>
                    {{ monthsNames[dateValue.getMonth()] }}
                    {{ dateValue.getFullYear() }}
                    <!-- {{ monthNames[month] }} {{ year }} -->
                </span>
                <span class="datapicker-arrows"> > </span>
            </div>
            <div class="datepicker-body">
                <div class="datepicker-row-weekdays">
                    <div
                        *ngFor="let day of weekDaysNames"
                        class="datepicker-day"
                    >
                        {{ day }}
                    </div>
                </div>
                <div *ngFor="let row of calendar" class="datepicker-row">
                    <div *ngFor="let day of row" class="datepicker-day">
                        {{ day < 10 ? '0' + day : day }}
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
